package org.rabochaya.maptests;
import android.app.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
/** Unexecuted baseline: real map gesture and real Activity destruction, never a process restart. */
final class MapUndoRotationChecks {
 final MapAndroidChecks m;final MapVertexConfirmationChecks c;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 MapUndoRotationChecks(MapAndroidChecks m){this.m=m;c=new MapVertexConfirmationChecks(m);g=c.g;v=c.v;r=c.r;}
 int count()throws Exception{return (Integer)m.call(m.vertexState(),"undoCount",new Class[]{});}
 boolean available()throws Exception{return (Boolean)m.call(m.vertexState(),"canUndo",new Class[]{});}
 void snapshot(String stage)throws Exception{JSONObject o=new JSONObject();o.put("stage",stage);o.put("project",m.editorField("project"));o.put("feature",m.editorField("featureId"));o.put("process",m.editorField("VERTEX_SESSION"));o.put("layout",c.layout());o.put("raw",m.editorText());o.put("key",g.key());o.put("token",m.editorField("expected"));o.put("selected",m.call(m.vertexState(),"selected",new Class[]{}));o.put("historyCount",count());o.put("canUndo",available());o.put("viewport",Arrays.toString((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})));m.capture("mvisual-map-undo-"+stage);v.emit("MAP_UNDO_VISUAL "+o.toString());}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(android.content.Context.class).newInstance(m.getTargetContext());long id=-1;try{id=g.fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));g.open(id,false);m.click("Редактировать на карте");m.mapEditorReady();String process=(String)m.editorField("VERTEX_SESSION");boolean retained=true;for(int rotation:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){String direction=rotation==UiAutomation.ROTATION_FREEZE_90?"land":"return",before=m.editorText(),token=(String)m.editorField("expected");m.dragVertex(1,14,8,false);String edited=m.editorText();int previous=count();m.check(!before.equals(edited)&&available()&&previous>0&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"real drag creates an undoable selected vertex edit");double[] viewport=((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})).clone();snapshot("before-"+direction);g.unchanged(store,id,xml,assets);Activity old=m.activity;c.rotate(rotation);snapshot("after-"+direction);m.check(old!=m.activity&&old.isDestroyed()&&c.layout().getBoolean("interactiveThreshold"),"undo probe actual destroyed/recreated and original80px guard");m.check((Long)m.editorField("project")==id&&"point".equals(m.editorField("featureId"))&&process.equals(m.editorField("VERTEX_SESSION"))&&m.editorText().equals(edited)&&g.key().equals("0")&&token.equals(m.editorField("expected"))&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"undo probe retains original raw/owner part/token/selected vertex");double[] current=(double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{});for(int axis=0;axis<3;axis++)m.check(Math.abs(current[axis]-viewport[axis])<1e-9,"undo probe retains original viewport");g.unchanged(store,id,xml,assets);int afterRotation=count();m.clickDescription("Удалить выбранную вершину");m.check(c.present(),"explicit map confirmation opens without touching Undo");m.click("Отмена");m.check(m.editorText().equals(edited)&&count()==afterRotation&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"Cancel keeps exact drag raw/selection/history without deletion");g.unchanged(store,id,xml,assets);boolean restored=available()&&count()==previous;retained&=restored;v.emit("MAP_UNDO_RECREATE direction="+direction+" oldDestroyed="+old.isDestroyed()+" previous="+previous+" current="+count()+" restored="+restored);if(restored){m.clickDescription("Отменить действие с вершиной");m.check(m.editorText().equals(before)&&count()==previous-1,"explicit Undo after actual recreation restores exact preceding raw");g.unchanged(store,id,xml,assets);snapshot("undone-"+direction);}}String finalRaw=m.editorText();int finalCount=count();m.click("Закрыть");m.click("Продолжить редактирование");m.check(m.editorText().equals(finalRaw)&&count()==finalCount,"cancelling editor closure preserves private raw/Undo");g.unchanged(store,id,xml,assets);snapshot("cancel-close");Object expectedDoc=r.parse(xml);org.w3c.dom.Element line=(org.w3c.dom.Element)m.element(expectedDoc,"point").getElementsByTagNameNS("*","LineString").item(0);StringBuilder coordinates=new StringBuilder();for(String row:finalRaw.split("\\n")){String[] xyz=row.trim().split("\\s+");if(coordinates.length()>0)coordinates.append(' ');coordinates.append(Double.parseDouble(xyz[1])).append(',').append(Double.parseDouble(xyz[0])).append(',').append(Double.parseDouble(xyz[2]));}((org.w3c.dom.Element)line.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent(coordinates.toString());m.click("Сохранить");m.geometryReady();m.mapEditorReady();m.check(m.treeToken(expectedDoc).equals(m.treeToken(r.load(store,id))),"only separate explicit Save updates addressed LineString, keeping all other DOM");r.sameAssets(r.load(store,id),assets);m.check(!available(),"successful explicit Save starts a fresh Undo scope");snapshot("saved");v.emit("MAP_UNDO_SAVE_CANCEL PASS");m.check(m.requests.get()==requests,"undo probe stays local");m.check(retained,"map Undo history survives both actual same-process Activity recreations");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);if(id>0)m.call(store,"remove",new Class[]{long.class},id);m.call(store,"close",new Class[]{});}}
}
